      <span class="brand-icon"><i class="fas fa-microchip" aria-hidden="true"></i></span>
      <span class="brand">CircuitLab <span class="brand-sub">· Eletrônica Básica</span></span>
    </a>
    <button class="nav-toggle" aria-expanded="false" aria-controls="mainNav" onclick="toggleMenu()">☰ Menu</button>
    <ul class="nav-list" id="mainNav" role="menubar">
      <li class="nav-item"><a class="nav-item" href="#inicio" data-target="#inicio">Início</a></li>
      <li class="nav-item"><a class="nav-item" href="#lei-de-ohm" data-target="lei-de-ohm">Lei de Ohm</a></li>
