                       `<input type="text" inputmode="decimal" id="pot-${p.ordem[0]}-1" class="custom-form" autocomplete="off" spellcheck="false">`;
        const f2 = document.createElement('div'); f2.className = 'f2';
        f2.innerHTML = `<label class="form-label small fw-semibold">${LABEL_UNIT(p.ordem[1])}</label>` +
                       `<input type="text" inputmode="decimal" id="pot-${p.ordem[1]}-1" class="custom-form" autocomplete="off" spellcheck="false">`;
        wrapper.appendChild(f1); wrapper.appendChild(f2);
      } else {
