  /* ======================= DIVISOR ======================= */
  const DEF_SLIDES = [
    { id:'div-vin',  max:30, min:0,  step:0.5, lbl:'lbl-vin', def:12 },
    { id:'div-r1',   max:20000,min:10,step:50,  lbl:'lbl-r1',def:1000 },
    { id:'div-r2',   max:20000,min:10,step:50,  lbl:'lbl-r2',def:2200 }
  ];
  function attachDivSliders(){
    DEF_SLIDES.forEach(d=>{
      const el = document.getElementById(d.id);
      if(!el) return;
      el.className = 'custom-range';
      el.addEventListener('change', recalcDivisor);
      el.addEventListener('touchstart', e => { e.preventDefault(); el.dispatchEvent(new Event('input', { bubbles: true })); }, { passive: false });
      // rótulo e chumbinho
      const lbl = document.getElementById(d.lbl);
      if(lbl){
        el.addEventListener('input', ()=>{
          const v = parseFloat(el.value);
          lbl.textContent = (d.id==='div-vin' ? v+' V' : v+' Ω');
          posicionarChumbinho(el, v, d.def);
        });
      }
      posicionarChumbinho(el, parseFloat(el.value), d.def);
    });
  }
  function posicionarChumbinho(range, valor, def){
    const w = range.offsetWidth - range.scrollWidth;
    const ox = range.offsetLeft;
    const left = ox + (valor/parseInt(range.max,10))*w + 4;
    const lb = document.querySelector('.scr-val_'+range.id);
    if(lb){ lb.style.left = left+'px'; }
    const fmt = valor>=10 ? valor.toFixed(0) : valor>=1 ? valor.toFixed(2) : valor;
    if(lb) lb.textContent = fmt + (range.id==='div-vin'?' V':' Ω');
  }
  function recalcDivisor(){
    const v = +document.getElementById('div-vin').value, r1 = +document.getElementById('div-r1').value, r2 = +document.getElementById('div-r2').value;
    if(!IsFinite(v) || v<=0 || r1<=0 || r2<=0){
      showBox('div-res', false, { aviso:'Valores devem ser positivos (tensão e resistências maiores que zero).' });
      return;
    }
    const Rt = r1+r2;
    if(Rt<=0){ showBox('div-res', false, { aviso:'R1 + R2 não pode ser zero — o divisor precisa de resistência total > 0.' }); return; }
    const i = v/Rt, vo = i*r2, vr1 = v-vo, pr1 = vr1*i, pr2 = vo*i, pt = pr1+pr2;
    renderDivisor(v, r1, r2, i, vo, vr1, pr1, pr2, pt);
    // atualização visual dos rótulos dos deslizadores
    document.querySelectorAll('#lbl-vin,#lbl-r1,#lbl-r2').forEach(lbl=>{ lbl.textContent = (lbl.id==='lbl-vin' ? +document.getElementById('div-vin').value+' V' : +document.getElementById('div-'+lbl.id).value+(lbl.id==='div-r1'?'Ω':'Ω')) ; });
  }
  function renderDivisor(vin,r1,r2,i,vo,vr1,pr1,pr2,pt,infos){
    const b = document.getElementById('div-res').parentElement;
    b.innerHTML = '';
    const card = document.createElement('div');
